32	  // would make the tagger's choice ambiguous. "Other" is the deliberate
33	  // exception: both lists need their own escape hatch, and a structured-output
34	  // call with no way to say "none of these" returns a confident wrong answer.
35	  const overlap = (TEXTURES as readonly string[]).filter((t) =>
