"use server";

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { TagSchema } from "@/lib/ai/tagging-schema";

const UpdateSchema = z.object({
  name: z.string().nullable(),
  brand: z.string().nullable(),
  category: TagSchema.shape.category,
  material: TagSchema.shape.material,
  formality: TagSchema.shape.formality,
  seasons: TagSchema.shape.seasons,
});

export async function updateItem(itemId: string, input: unknown) {
  const data = UpdateSchema.parse(input);
  const supabase = await createClient();
  // RLS scopes this to the owner's rows; a foreign id simply matches 0 rows.
  const { error } = await supabase
    .from("items")
    .update({
      name: data.name,
      brand: data.brand,
      category: data.category,
      material: data.material,
      formality: data.formality,
      seasons: data.seasons,
    })
    .eq("id", itemId);
  if (error) throw error;
  revalidatePath("/closet");
  revalidatePath(`/closet/${itemId}`);
}

export async function archiveItem(itemId: string) {
  const supabase = await createClient();
  const { error } = await supabase
    .from("items")
    .update({ archived: true })
    .eq("id", itemId);
  if (error) throw error;
  revalidatePath("/closet");
  redirect("/closet");
}

import {
  TagSchema,
  MATERIALS as AI_MATERIALS,
  TEXTURES as AI_TEXTURES,
} from "@/lib/ai/tagging-schema";

/**
 * The single source for every closet vocabulary.
 *
 * These lists were previously copy-pasted into confirm-form.tsx and
 * item-detail.tsx, and neither copy matched what the tagger was told to emit —
 * so the AI could write a material the edit screen could not offer back.
 * Categories and seasons are DERIVED from TagSchema so drift is impossible;
 * the rest are defined here and consumed by the schema.
 */

export const CATEGORIES = TagSchema.shape.category.options;
export const SEASONS = TagSchema.shape.seasons.element.options;

export const FORMALITY_LABEL = [
  "",
  "Very casual",
  "Casual",
  "Smart casual",
  "Business",
  "Formal",
] as const;

/**
 * Materials and textures are DEFINED in `lib/ai/tagging-schema.ts` and
 * re-exported here, not the other way round: this module derives CATEGORIES and
 * SEASONS from `TagSchema`, so importing vocab from the schema would be a
 * cycle. Every UI surface still reads them from here, so there is one import
 * path for the whole closet vocabulary.
 */
export const MATERIALS = AI_MATERIALS;
export const TEXTURES = AI_TEXTURES;

export const PATTERNS = ["solid", "striped", "check", "print", "other"] as const;

/**
 * The palette the swatch picker offers. Names match what the tagger emits and
 * what `lib/generator/color.ts` groups into families — a colour the generator
 * cannot place is a colour that silently scores nothing.
 */
export const COLORS = [
  { name: "black", hex: "#141414" },
  { name: "charcoal", hex: "#36353a" },
  { name: "grey", hex: "#8a8a8f" },
  { name: "white", hex: "#f4f1ea" },
  { name: "cream", hex: "#ece3d2" },
  { name: "stone", hex: "#cabfae" },
  { name: "beige", hex: "#d5c4a8" },
  { name: "camel", hex: "#b08d57" },
  { name: "tan", hex: "#a9784f" },
  { name: "brown", hex: "#6b4b32" },
  { name: "rust", hex: "#b86a47" },
  { name: "burgundy", hex: "#5e2733" },
  { name: "olive", hex: "#5e7256" },
  { name: "green", hex: "#3f6b4a" },
  { name: "navy", hex: "#242f45" },
  { name: "blue", hex: "#3d5a80" },
  { name: "denim", hex: "#5a7896" },
  { name: "pink", hex: "#d0a0a0" },
  { name: "yellow", hex: "#d6b756" },
  { name: "silver", hex: "#c0c0c8" },
  { name: "gold", hex: "#c9a227" },
] as const;

export function colorHex(name: string): string | undefined {
  const n = name.toLowerCase();
  return COLORS.find((c) => c.name === n)?.hex;
}

import { z } from "zod";

// MATERIALS and TEXTURES are defined HERE rather than imported from
// lib/closet/vocab.ts: vocab derives CATEGORIES/SEASONS from this schema, so
// importing back would be a cycle. `vocab.ts` re-exports these two, and remains
// the module every UI surface reads from.

/**
 * What the garment is made of.
 *
 * `Merino wool` is listed separately from `Wool` on purpose: they behave
 * differently in heat, and one undifferentiated "wool" is exactly the
 * conflation that makes warmth rules wrong. Warmth is decided by fibre AND
 * construction — see TEXTURES.
 */
export const MATERIALS = [
  "Cotton",
  "Wool",
  "Merino wool",
  "Cashmere",
  "Linen",
  "Silk",
  "Denim",
  "Leather",
  "Suede",
  "Faux leather",
  "Canvas",
  "Corduroy",
  "Tweed",
  "Fleece",
  "Shearling",
  "Down",
  "Polyester",
  "Acrylic",
  "Nylon",
  "Viscose",
  "Modal",
  "Lyocell",
  "Stainless steel",
  "Gold",
  "Silver",
  "Rubber",
  "Other",
] as const;

/**
 * How the fabric is built — knit structure and surface finish. A separate
 * dimension from material: a ribbed merino knit and a flat merino shirt share a
 * material and read completely differently, in both warmth and formality.
 *
 * `Other` is the escape hatch, and the one value deliberately shared with
 * MATERIALS. Without it a required `z.enum` forces the model to mislabel rather
 * than admit it cannot tell from a photo.
 */
export const TEXTURES = [
  "Flat",
  "Ribbed",
  "Cable knit",
  "Waffle",
  "Chunky knit",
  "Fine knit",
  "Brushed",
  "Fleece-back",
  "Twill",
  "Herringbone",
  "Quilted",
  "Pile",
  "Open knit",
  "Terry",
  "Seersucker",
  "Other",
] as const;

// Categories + seasons match the prototype (Title case) so tags line up with
// the closet filters and the generator.
export const TagSchema = z.object({
  category: z.enum(["Tops", "Bottoms", "Outerwear", "Shoes", "Accessories", "Fragrance"]),
  subcategory: z.string().min(1),
  colors: z.array(z.string()).min(1).max(3),
  pattern: z.enum(["solid", "striped", "check", "print", "other"]),
  material: z.enum(MATERIALS),
  texture: z.enum(TEXTURES),
  formality: z.number().int().min(1).max(5),
  seasons: z.array(z.enum(["Spring", "Summer", "Autumn", "Winter"])).min(1),
});
export type Tags = z.infer<typeof TagSchema>;

// Anthropic structured outputs (output_config.format) only accept type/enum/shape
// keywords — NOT the numeric (minimum/maximum/multipleOf), string (min/maxLength),
// or array (min/maxItems/uniqueItems) validation keywords that z.toJSONSchema()
// emits from our .min()/.max()/.int() refinements. Sending them 400s. We strip them
// here; the exact bounds are still enforced after the call by TagSchema.parse().
const UNSUPPORTED_JSON_SCHEMA_KEYWORDS = new Set([
  "minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "multipleOf",
  "minLength", "maxLength",
  "minItems", "maxItems", "uniqueItems",
]);

export function forStructuredOutput(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(forStructuredOutput);
  if (node && typeof node === "object") {
    const out: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(node)) {
      if (UNSUPPORTED_JSON_SCHEMA_KEYWORDS.has(key)) continue;
      out[key] = forStructuredOutput(value);
    }
    // Structured outputs require every object to forbid extra properties.
    if (out.type === "object" && !("additionalProperties" in out)) {
      out.additionalProperties = false;
    }
    return out;
  }
  return node;
}

// Zod 4 native JSON Schema, sanitised for Anthropic's output_config.format.
export const taggingJsonSchema = forStructuredOutput(
  z.toJSONSchema(TagSchema),
) as Record<string, unknown>;
